/** Synchronous native Infinity outcomes; real300tick cadence is intentionally a separate async qualification. */
public final class InfinityChecks {
    private InfinityChecks(){}
    private static void require(boolean ok,String why){if(!ok)throw new IllegalStateException("Infinity: "+why);}
    private static java.lang.reflect.Field field(Object value,String name){for(Class<?> t=value.getClass();t!=null;t=t.getSuperclass())try{var f=t.getDeclaredField(name);f.setAccessible(true);return f;}catch(NoSuchFieldException ignored){}throw new IllegalStateException(name);}
    private static Object read(Object v,String n){try{return field(v,n).get(v);}catch(IllegalAccessException e){throw new IllegalStateException(e);}}
    private static void set(Object v,String n,Object x){try{field(v,n).set(v,x);}catch(IllegalAccessException e){throw new IllegalStateException(e);}}
    private static final class State {
        final ServerPlayer player;final GameChecks.WandThirdPlayerState state;final boolean ground,sprint,shift;final Vec3 known;final net.minecraft.world.entity.Pose pose;
        final net.minecraft.world.entity.ai.attributes.AttributeMap attributes=new net.minecraft.world.entity.ai.attributes.AttributeMap(net.minecraft.world.entity.ai.attributes.DefaultAttributes.getSupplier(EntityTypes.PLAYER));
        final Map<net.minecraft.stats.Stat<?>,Integer> stats=new LinkedHashMap<>();final Map<net.minecraft.world.scores.Objective,Integer> scores=new LinkedHashMap<>();
        final Map<java.lang.reflect.Field,Object> values=new LinkedHashMap<>(),combat=new LinkedHashMap<>(),food=new LinkedHashMap<>(),profile=new LinkedHashMap<>();
        final Map<net.minecraft.advancements.AdvancementHolder,Set<String>> advancements=new LinkedHashMap<>();final Map<EquipmentSlot,ItemStack> equipment=new EnumMap<>(EquipmentSlot.class);
        State(GameController game,ServerPlayer p){player=p;require(!p.isUsingItem(),"fixture starts with idle hands");state=new GameChecks.WandThirdPlayerState(p,game.items().mana());ground=p.onGround();sprint=p.isSprinting();shift=p.isShiftKeyDown();known=p.getKnownMovement();pose=p.getPose();
            for(var h:net.minecraft.core.registries.BuiltInRegistries.ATTRIBUTE.listElements().toList()){var a=p.getAttribute(h);if(a!=null)attributes.getInstance(h).replaceFrom(a);}
            for(var id:net.minecraft.core.registries.BuiltInRegistries.CUSTOM_STAT){var s=Stats.CUSTOM.get(id);stats.put(s,p.getStats().getValue(s));}for(var type:List.of(Stats.ITEM_USED,Stats.ITEM_BROKEN))for(var item:List.of(Items.SHIELD,Items.LEATHER_BOOTS,Items.LEATHER_LEGGINGS,Items.LEATHER_CHESTPLATE,Items.LEATHER_HELMET)){var s=type.get(item);stats.put(s,p.getStats().getValue(s));}
            for(var objective:game.server().getScoreboard().getObjectives()){var score=game.server().getScoreboard().getPlayerScoreInfo(p,objective);if(score!=null)scores.put(objective,score.value());}
            for(var a:game.server().getAdvancements().getAllAdvancements()){var done=new HashSet<String>();p.getAdvancements().getOrStartProgress(a).getCompletedCriteria().forEach(done::add);advancements.put(a,done);}
            for(var name:List.of("attackStrengthTicker","itemSwapTicker","xxa","yya","zza","jumping","yHeadRot","yHeadRotO","hurtTime","hurtDuration","lastHurt","lastDamageStamp","lastDamageSource","lastRecordedFoodLevel","lastSentFood","lastFoodSaturationZero","lastSentHealth","lastRecordedHealthAndAbsorption"))values.put(field(p,name),read(p,name));
            try{for(var f:p.getCombatTracker().getClass().getDeclaredFields())if(!java.lang.reflect.Modifier.isStatic(f.getModifiers())){f.setAccessible(true);var v=f.get(p.getCombatTracker());if(v instanceof List<?> list)combat.put(f,new ArrayList<>(list));else if(!java.lang.reflect.Modifier.isFinal(f.getModifiers()))combat.put(f,v);}for(var f:p.getFoodData().getClass().getDeclaredFields())if(!java.lang.reflect.Modifier.isStatic(f.getModifiers())){f.setAccessible(true);food.put(f,f.get(p.getFoodData()));}for(var f:game.players().get(p.getUUID()).getClass().getFields())if(!java.lang.reflect.Modifier.isStatic(f.getModifiers())){var v=f.get(game.players().get(p.getUUID()));profile.put(f,v instanceof int[] a?a.clone():v instanceof Set<?> s?new HashSet<>(s):v);}for(var entry:((Map<?,?>)read(p,"lastEquipmentItems")).entrySet())equipment.put((EquipmentSlot)entry.getKey(),((ItemStack)entry.getValue()).copy());}catch(IllegalAccessException e){throw new IllegalStateException(e);}
        }
        @SuppressWarnings({"rawtypes","unchecked"}) void restore(GameController game){state.restore(game);player.getAttributes().assignAllValues(attributes);player.setHealth(state.health);player.setAbsorptionAmount(state.absorption);player.setOnGround(ground);player.setSprinting(sprint);player.setShiftKeyDown(shift);player.setKnownMovement(known);player.setPose(pose);stats.forEach((s,v)->player.getStats().setValue(player,s,v));for(var o:game.server().getScoreboard().getObjectives())if(scores.containsKey(o))game.server().getScoreboard().getOrCreatePlayerScore(player,o,true).set(scores.get(o));else game.server().getScoreboard().resetSinglePlayerScore(player,o);advancements.forEach((a,done)->{for(var key:a.value().criteria().keySet())if(done.contains(key))player.getAdvancements().award(a,key);else player.getAdvancements().revoke(a,key);});
            try{for(var e:values.entrySet())e.getKey().set(player,e.getValue());for(var e:combat.entrySet())if(e.getValue() instanceof List old){var current=(List)e.getKey().get(player.getCombatTracker());current.clear();current.addAll(old);}else e.getKey().set(player.getCombatTracker(),e.getValue());for(var e:food.entrySet())e.getKey().set(player.getFoodData(),e.getValue());for(var e:profile.entrySet())e.getKey().set(game.players().get(player.getUUID()),e.getValue());var equipmentMap=(Map<EquipmentSlot,ItemStack>)read(player,"lastEquipmentItems");equipmentMap.clear();equipment.forEach((s,i)->equipmentMap.put(s,i.copy()));}catch(IllegalAccessException e){throw new IllegalStateException(e);}
        }
    }

    private static ItemStack raw(int count,boolean outer){var s=new ItemStack(Items.REPEATING_COMMAND_BLOCK,count);var d=new net.minecraft.nbt.CompoundTag();d.putInt("infinity_rand",1);if(outer)d.putInt("instantitem",1);s.set(DataComponents.CUSTOM_DATA,CustomData.of(d));return s;}
    private static final Identifier LARGE=Identifier.parse("minecraft:infinity_scale"),SMALL=Identifier.parse("minecraft:infinity_scale1");
    private static AttributeInstance attr(ServerPlayer p,String id){return p.getAttribute(p.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ATTRIBUTE).getOrThrow(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.ATTRIBUTE,Identifier.parse("minecraft:"+id))));}
    private static void near(double a,double b,String why){require(Math.abs(a-b)<.000001,why+" actual="+a+" expected="+b);}
    private static void base(ServerPlayer p,String id,double value){near(attr(p,id).getBaseValue(),value,"native base "+id);}
    private static void mod(ServerPlayer p,String id,Identifier key,double amount,AttributeModifier.Operation op){var m=attr(p,id).getModifier(key);require(m!=null&&m.operation()==op,"native modifier "+id);near(m.amount(),amount,"source modifier amount "+id);}
    private static void prepare(ServerPlayer p){p.removeAllEffects();p.getInventory().clearContent();for(var slot:List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET,EquipmentSlot.MAINHAND,EquipmentSlot.OFFHAND))p.setItemSlot(slot,ItemStack.EMPTY);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.getAbilities().invulnerable=false;for(var tag:List.of("infinite_resistance","infinite_heal","infinite_saturation","time_stopped","spectator","strict_map_object","magic_academy","rcdenyalways","sin_greed_active","nomagic_active"))p.entityTags().remove(tag);for(var h:net.minecraft.core.registries.BuiltInRegistries.ATTRIBUTE.listElements().toList()){var a=p.getAttribute(h);if(a!=null){a.removeModifier(LARGE);a.removeModifier(SMALL);}}p.setHealth(Math.min(10,p.getMaxHealth()));}
    /** Same scoped native random fixture used by the armor checks; only Infinity's14way draw is replaced. */
    static int select(LbcInfinity service,ServerPlayer p,int branch){var original=read(p,"random");int[] draws={0};try{set(p,"random",java.lang.reflect.Proxy.newProxyInstance(net.minecraft.util.RandomSource.class.getClassLoader(),new Class<?>[]{net.minecraft.util.RandomSource.class},(proxy,m,args)->{if(m.getName().equals("nextInt")&&args!=null&&args.length==1&&args[0].equals(14)&&StackWalker.getInstance().walk(frames->frames.anyMatch(f->f.getClassName().equals(LbcInfinity.class.getName())))){draws[0]++;return branch-1;}try{return m.invoke(original,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}}));int result=service.tickPlayer(p);require(result==branch&&draws[0]==1,"actual source14way selector "+branch);return result;}finally{set(p,"random",original);}}
    private static void normalMovement(ServerPlayer p){for(var name:List.of("movement_speed","gravity"))require(!attr(p,name).hasModifier(LARGE),"small Infinity cancels large compensation for "+name);}
    private static void sizeOrder(GameController game,ServerPlayer p){
        var unrelated=Identifier.parse("skywars2:infinity_fixture_unrelated");
        for(var sequence:List.of(List.of(13,14),List.of(14,13),List.of(13,13,14,13),List.of(14,14,13,14))){var saved=new State(game,p);try{
            prepare(p);p.getInventory().setItem(9,raw(sequence.size()+1,true));
            attr(p,"movement_speed").addTransientModifier(new AttributeModifier(unrelated,.023,AttributeModifier.Operation.ADD_VALUE));
            attr(p,"gravity").addTransientModifier(new AttributeModifier(unrelated,.011,AttributeModifier.Operation.ADD_VALUE));
            double speed=attr(p,"movement_speed").getValue(),gravity=attr(p,"gravity").getValue();boolean small=false;
            for(int branch:sequence){select(new LbcInfinity(game),p,branch);small|=branch==14;if(small){normalMovement(p);near(attr(p,"movement_speed").getValue(),speed,"size order restores normal speed with unrelated bonus");near(attr(p,"gravity").getValue(),gravity,"size order restores normal gravity with unrelated bonus");}else{near(attr(p,"movement_speed").getValue(),speed*17,"large-only compensation retained");near(attr(p,"gravity").getValue(),gravity*17,"large-only gravity retained");}}
            require(p.getInventory().getItem(9).getCount()==1,"every size activation consumes exactly one item");
        }finally{saved.restore(game);}}
    }
    private static void outcomes(GameController game,ServerPlayer p){
        for(int b=1;b<=14;b++){var saved=new State(game,p);try{prepare(p);p.getInventory().setItem(9,raw(2,true));var service=new LbcInfinity(game);select(service,p,b);require(p.getInventory().getItem(9).getCount()==1,"one actual source clear branch"+b);require(service.tickPlayer(p)==0&&p.getInventory().getItem(9).getCount()==1,"same tick admission guard");
            switch(b){
                case 1->require(game.items().mana().maximum(p)==100000000,"native maxmana");
                case 2->require(game.items().mana().baseRegen(p)==100000000,"native manaregen");
                case 3->{base(p,"armor",10000000);base(p,"armor_toughness",10000000);base(p,"burning_time",-1000000);}
                case 4->base(p,"attack_damage",100000000);
                case 5->{base(p,"attack_speed",10000000);base(p,"block_break_speed",214708364);}
                case 6->{base(p,"knockback_resistance",10000000);base(p,"explosion_knockback_resistance",10000000);}
                case 7->{base(p,"max_health",214708364);near(p.getHealth(),10,"no invented health refill");}
                case 8,9,10->{String tag=b==8?"infinite_resistance":b==9?"infinite_heal":"infinite_saturation";var effect=b==8?MobEffects.RESISTANCE:b==9?MobEffects.INSTANT_HEALTH:MobEffects.SATURATION;require(p.entityTags().contains(tag),"native permanent source tag");require(!p.hasEffect(effect),"tag waits source300pulse");service.pulse300(p);var e=p.getEffect(effect);require(e!=null&&e.getDuration()==-1&&e.getAmplifier()==ItemEffectLevels.amplifier(effect,b==8?4:b==9?99:50),"native infinite effect through shared caps");}
                case 11->{ItemStack wand=ItemStack.EMPTY;for(int i=0;i<36;i++)if(LbcFartus.data(p.getInventory().getItem(i)).getIntOr("luckyblockwand",0)==1)wand=p.getInventory().getItem(i);require(wand.is(Items.CARROT_ON_A_STICK)&&wand.getCount()==1,"literal source wand native give");require(Identifier.parse("lbc:lucky_block").equals(wand.get(DataComponents.ITEM_MODEL))&&Identifier.parse("lbc:tier_u").equals(wand.get(DataComponents.TOOLTIP_STYLE)),"literal command presentation differs original separate lootleaf");require(net.minecraft.world.item.enchantment.EnchantmentHelper.getItemEnchantmentLevel(p.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.INFINITY),wand)==1,"native Infinity enchantment");}
                case 12->{base(p,"fall_damage_multiplier",-1);for(var id:List.of("movement_efficiency","water_movement_efficiency","step_height","sneaking_speed","safe_fall_distance","oxygen_bonus"))base(p,id,10000000);}
                case 13->{for(var id:List.of("scale","attack_damage","explosion_knockback_resistance","jump_strength","knockback_resistance","max_health","movement_efficiency","movement_speed","safe_fall_distance","step_height","water_movement_efficiency","block_break_speed","mining_efficiency","gravity"))mod(p,id,LARGE,16,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);mod(p,"attack_knockback",LARGE,16,AttributeModifier.Operation.ADD_VALUE);mod(p,"fall_damage_multiplier",LARGE,-.9375,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);mod(p,"block_interaction_range",LARGE,32,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);mod(p,"entity_interaction_range",LARGE,32,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);mod(p,"sweeping_damage_ratio",LARGE,1,AttributeModifier.Operation.ADD_VALUE);var next=new LbcInfinity(game);select(next,p,14);normalMovement(p);mod(p,"scale",SMALL,-.9375,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);}
                case 14->{mod(p,"scale",SMALL,-.9375,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);mod(p,"safe_fall_distance",SMALL,10000,AttributeModifier.Operation.ADD_VALUE);mod(p,"fall_damage_multiplier",SMALL,-1,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);normalMovement(p);}
            }
            var a=game.server().getAdvancements().get(Identifier.parse("lbc:true_advancements/legends/infinity"));require(a!=null&&p.getAdvancements().getOrStartProgress(a).isDone(),"actual source advancement award");
        }finally{saved.restore(game);}}
    }
    private static void admission(GameController game,ServerPlayer p){var saved=new State(game,p);try{prepare(p);var mana=game.items().mana();mana.score(net.minecraft.world.scores.ScoreHolder.forNameOnly("#lbcskill"),"swrg.math").set(1);mana.score(p,"lbc.skill").set(2);p.getInventory().setItem(9,raw(2,true));var service=new LbcInfinity(game);require(service.tickPlayer(p)==0&&p.getInventory().getItem(9).getCount()==2,"skill2 requires selected item");p.setItemSlot(EquipmentSlot.MAINHAND,raw(1,true));select(service,p,1);int remaining=0;for(int i=0;i<36;i++)if(LbcInfinity.instant(p.getInventory().getItem(i)))remaining+=p.getInventory().getItem(i).getCount();require(remaining==2,"skill2 still global nativeclear exactly one");prepare(p);p.setItemSlot(EquipmentSlot.OFFHAND,raw(1,false));require(new LbcInfinity(game).tickPlayer(p)==0,"outer actual instantitem flag required");p.setItemSlot(EquipmentSlot.OFFHAND,raw(1,true));mana.score(p,"lbc.skill").set(0);select(new LbcInfinity(game),p,2);require(p.getOffhandItem().isEmpty(),"ordinary anyInventory includes offhand");}finally{saved.restore(game);}}
    private static void producer(GameController game,ServerPlayer p){var board=game.server().getScoreboard();var before=board.getPlayerTeam("bluegays");var color=before==null?null:before.getColor();ItemEntity item=null;try{item=new LbcInfinity(game).produce(p.level(),p.position().add(0,3,0),p);require(item!=null&&!item.isRemoved()&&item.getOwner()==p&&game.items().currentEpoch(item),"real native producer admitted with causal wearer and epoch");require(item.isNoGravity()&&item.isCurrentlyGlowing()&&item.isCustomNameVisible()&&item.getAge()==-32768,"source grounded reward traits and age");require(item.entityTags().contains("itemteamblue")&&item.getTeam()==board.getPlayerTeam("bluegays"),"native Aqua source team");require(LbcInfinity.instant(item.getItem())&&LbcFartus.data(item.getItem()).getIntOr("instantitem",0)==1&&Identifier.parse("lbc:infinity").equals(item.getItem().get(DataComponents.ITEM_MODEL))&&Identifier.parse("lbc:tier_x").equals(item.getItem().get(DataComponents.TOOLTIP_STYLE)),"exact native raw instant reward flags/model/tier");}finally{if(item!=null){if(item.getTeam()!=null)board.removePlayerFromTeam(item.getScoreboardName(),item.getTeam());game.items().entityUnloaded(item);item.discard();}if(before==null){var team=board.getPlayerTeam("bluegays");if(team!=null)board.removePlayerTeam(team);}else before.setColor(color);}}
    public static void run(GameController game){var p=Objects.requireNonNull(game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestAlpha")));require(game.playing()&&game.canUseGameplayItems(p)&&p.containerMenu==p.inventoryMenu&&!p.isUsingItem()&&!game.items().timeStop().stopped(p.level()),"real ordinary idle match participant");var mana=game.items().mana();var holder=net.minecraft.world.scores.ScoreHolder.forNameOnly("#lbcskill");var objective=game.server().getScoreboard().getObjective("swrg.math");var prior=objective==null?null:game.server().getScoreboard().getPlayerScoreInfo(holder,objective);Integer old=prior==null?null:prior.value();try{mana.score(holder,"swrg.math").set(0);outcomes(game,p);sizeOrder(game,p);admission(game,p);producer(game,p);}finally{var current=game.server().getScoreboard().getObjective("swrg.math");if(old==null)game.server().getScoreboard().resetSinglePlayerScore(holder,current);else game.server().getScoreboard().getOrCreatePlayerScore(holder,current,true).set(old);if(objective==null)game.server().getScoreboard().removeObjective(current);}SkyWars2.LOGGER.info("[check] PASS infinity (14 real inventory outcomes, skill2 admission, native attributes/duplicate IDs/infinite effects and causal item producer; source300tick cadence and shared dispatcher remain pending asynchronous checks)");}
}
